class SSEResponse(StreamingResponse):
    """SSE response for Server-Sent Events.

    **Note**: `SSEResponse` is a wrapper around `StreamingResponse` that sets the
    correct `media_type` and headers for SSE.
    """

    def __init__(
        self,
        content: Any,
        status_code: int = 200,
        headers: Any = None,
        background: Any = None,
        media_type: str = "text/event-stream",
    ):
        if headers is None:
            headers = {}
        else:
            headers = headers.copy()
        headers["Cache-Control"] = "no-cache"
        headers["Connection"] = "keep-alive"
